import{_ as t,o as n,c as r,a2 as o}from"./chunks/framework.CtQGab4e.js";const h=JSON.parse('{"title":"Constructies en correcties","description":"","frontmatter":{},"headers":[],"relativePath":"plattegrond/constructies.md","filePath":"plattegrond/constructies.md"}'),a={name:"plattegrond/constructies.md"};function i(d,e,s,l,g,c){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="constructies-en-correcties" tabindex="-1">Constructies en correcties <a class="header-anchor" href="#constructies-en-correcties" aria-label="Permalink to &quot;Constructies en correcties&quot;">​</a></h1><p>Na <strong>Genereer</strong> staat naast het 3D-model (of eronder) de berekening: per zone de <strong>constructies</strong> met hun oppervlaktes. Een constructie is bijvoorbeeld <em>Voorgevel</em>, <em>Dak hellend achter</em> of <em>Vloer</em>. Hier controleer je de uitkomst en pas je hem aan waar nodig. Zie eerst <a href="./3d-paneel.html">Het 3D-paneel</a>.</p><h2 id="een-constructie-lezen" tabindex="-1">Een constructie lezen <a class="header-anchor" href="#een-constructie-lezen" aria-label="Permalink to &quot;Een constructie lezen&quot;">​</a></h2><p>Per constructie zie je:</p><ul><li>de <strong>naam</strong>, bijvoorbeeld <em>Achtergevel - AOR</em>;</li><li>daaronder vlaktype, helling, windrichting en begrenzing, bijvoorbeeld <em>gevel · 90° · Z · buiten</em>;</li><li>de <strong>rijen</strong>: per rij een lengte <strong>L</strong> en een breedte <strong>B</strong>, met de uitkomst in m². Een negatieve rij trekt iets af, bijvoorbeeld een stuk onder een dakkapel;</li><li>het <strong>totaal</strong> in m².</li></ul><p>Tik op een constructie (of op een vlak in het model) om hem in het model te zien, met de maatlijnen en rijnummers. Tik op een rij om alleen die rij te zien.</p><p>Met de filterknoppen bovenaan kies je wat je ziet: <strong>Alles</strong>, <strong>Meer sommen</strong> (constructies met twee of meer rijen) of <strong>Eén som</strong>.</p><h2 id="aanpassen" tabindex="-1">Aanpassen <a class="header-anchor" href="#aanpassen" aria-label="Permalink to &quot;Aanpassen&quot;">​</a></h2><p>Alles wat je hier wijzigt, heet een <strong>correctie</strong>.</p><table tabindex="0"><thead><tr><th>Wat</th><th>Hoe</th></tr></thead><tbody><tr><td><strong>Naam wijzigen</strong></td><td>Tik op de naam en typ. <kbd>Enter</kbd> legt hem vast, <kbd>Esc</kbd> zet de oude terug.</td></tr><tr><td><strong>Een maat wijzigen</strong></td><td>Tik op L of B en typ. Een som mag ook, bijvoorbeeld <code>2,40+1,10</code>.</td></tr><tr><td><strong>Rij toevoegen</strong></td><td><strong>+ Rij toevoegen</strong>, en vul L en B in. Een negatieve B trekt af.</td></tr><tr><td><strong>Rij verwijderen</strong></td><td><strong>×</strong> voor de rij.</td></tr><tr><td><strong>Terug naar de 3D-server</strong></td><td><strong>Herstellen</strong>: deze constructie weer zoals de 3D-server hem gaf.</td></tr><tr><td><strong>Constructie verwijderen</strong></td><td><strong>- Constructie verwijderen</strong>. Hij gaat uit de berekening, en wordt in het model lichtgrijs.</td></tr><tr><td><strong>Terugzetten</strong></td><td>Onderaan staat <strong>Verwijderde constructies</strong>. Tik daar op <strong>Terugzetten</strong>.</td></tr></tbody></table><p>Bij een constructie van de 3D-server zonder rijen (alleen een totaal) kun je geen rijen toevoegen.</p><p>Je correcties worden bij de notitie bewaard, maar vervallen bij een nieuw model (zie <a href="./3d-paneel.html#genereren">Genereren</a>). Corrigeer dus pas als de tekening af is.</p><h2 id="constructie-toevoegen" tabindex="-1">Constructie toevoegen <a class="header-anchor" href="#constructie-toevoegen" aria-label="Permalink to &quot;Constructie toevoegen&quot;">​</a></h2><p>Ontbreekt er iets, voeg het dan zelf toe met <strong>+ Constructie toevoegen</strong>. Heb je een constructie gekozen, dan zijn de velden al ingevuld zoals die constructie, en komt de nieuwe eronder.</p><table tabindex="0"><thead><tr><th>Veld</th><th>Wat je kunt kiezen</th></tr></thead><tbody><tr><td><strong>Naam</strong></td><td>Vrij, bijvoorbeeld <em>Gevel dakkapel</em>.</td></tr><tr><td><strong>Zone</strong> en <strong>Gebouwdeel</strong></td><td>Uit de zones en gebouwdelen van het model.</td></tr><tr><td><strong>Vlaktype</strong></td><td>vloer, vloer boven buitenlucht, kelderwand, gevel of dak.</td></tr><tr><td><strong>Begrenzing</strong></td><td>Alleen wat bij het vlaktype hoort, bijvoorbeeld <em>grond</em> bij een kelderwand.</td></tr><tr><td><strong>Windrichting</strong></td><td>N tot en met NW. Bij een dak ook <strong>HOR</strong>. Niet bij vloeren, een kelderwand of een begrenzing AOR of SGR.</td></tr><tr><td><strong>Helling</strong></td><td>Een gevel 76 tot en met 164° (standaard 90°), een dak 0 tot en met 75°. Een vloer is 0°, een kelderwand 90°.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Plat of hellend dak</p><p>Een dak onder 15° is een <strong>plat dak</strong>: dat heeft windrichting <strong>HOR</strong>. Kies je HOR, dan wordt de helling 0°. Vul je een helling onder 15° in, dan wordt de windrichting HOR. Kies je bij een plat dak een windrichting, dan moet je de helling opnieuw invullen (15° of meer).</p></div><p>Daarna staat er meteen een nieuwe rij klaar: vul L en B in.</p><h2 id="correcties-van-een-andere-berekening" tabindex="-1">Correcties van een andere berekening <a class="header-anchor" href="#correcties-van-een-andere-berekening" aria-label="Permalink to &quot;Correcties van een andere berekening&quot;">​</a></h2><p>Zie je <em>Je correcties horen bij een andere berekening van de 3D-server</em>? Dan kun je ze alleen nog bekijken. Met <strong>Correcties verwerpen</strong> toont het paneel weer de berekening van de 3D-server.</p>',19)])])}const m=t(a,[["render",i]]);export{h as __pageData,m as default};
